use std::fs

fn main() {
    let limit = 200000
    let mut sieve: Vec<bool> = [true; 200001]
    let mut count: Vec<int> = [0; 200001]
    let mut largest: Vec<int> = [0; 200001]
    sieve[0] = false
    sieve[1] = false
    let mut i = 2
    while i * i <= limit {
        if sieve[i] {
            let mut j = i * i
            while j <= limit {
                sieve[j] = false
                j += i
            }
        }
        i += 1
    }
    let mut c = 0
    let mut last = 0
    let mut k = 0
    while k <= limit {
        if sieve[k] {
            c += 1
            last = k
        }
        count[k] = c
        largest[k] = last
        k += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut out: Vec<string> = []
    for line in text.lines() {
        let t = line.trim()
        if t == "" {
            continue
        }
        if first {
            first = false
            continue
        }
        let n = t.parse::<int>().unwrap_or(0)
        if n < 2 {
            out.push("0 none")
        } else {
            out.push("${count[n]} ${largest[n]}")
        }
    }
    println(out.join("\n"))
}

